import React from 'react';

const events = [
  { month: 'MAY', day: '10' },
  { month: 'JULY', day: '10' },
  { month: 'MON', day: 'DD' },
];

export default function Events() {
  return (
    <section className="text-center px-[5vw] mb-20">
<h2 className="mb-8 text-[clamp(2rem,5vw,2.75rem)] font-extrabold text-[#292929] tracking-tight">
  Upcoming <span className="text-[#F48F0F]">Events</span>
</h2>

      <div className="flex flex-col gap-8">
        {events.map(({ month, day }, idx) => (
          <div
            key={idx}
            className="flex flex-col sm:flex-row items-start sm:items-center bg-white p-6 rounded-2xl shadow-md border border-[#e4e4e4] hover:shadow-xl transition-shadow duration-300"
          >
            <div className="bg-[#F48F0F] text-white text-center rounded-xl py-3 px-4 w-24 text-[clamp(1rem,2vw,1.25rem)] font-bold">
              {month}
              <br />
              {day}
            </div>

            <div className="text-left mt-4 sm:mt-0 sm:ml-6 flex-1">
              <strong className="font-semibold text-[clamp(1.125rem,2.2vw,1.5rem)] text-[#292929]">
                Event name goes here
              </strong>
              <p className="text-[clamp(0.95rem,1.7vw,1.05rem)] mt-2 text-[#444] leading-snug">
                Event description or details would be displayed here (max 2 lines)
              </p>
            </div>
          </div>
        ))}
      </div>

      <button className="mt-10 bg-[#F48F0F] text-[#292929] py-3 px-7 rounded-full font-semibold text-[clamp(0.95rem,1.5vw,1.05rem)] hover:brightness-105 transition duration-200">
        View All Events
      </button>
    </section>
  );
}
